guided.solution:
CREATE TABLE item_feed (version_id int, sku text, price int, updated_at date);
INSERT INTO item_feed VALUES (1,'A',100,'2025-03-01'),(2,'A',120,'2025-03-05'),(3,'B',50,'2025-03-02'),(4,'B',55,'2025-03-02'),(5,'C',70,'2025-03-03');
SELECT sku, price
FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY sku ORDER BY updated_at DESC, version_id DESC) AS rn FROM item_feed) t
WHERE rn = 1
ORDER BY sku;

