guided.solution:
CREATE TABLE daily_sales (day date, cents int);
INSERT INTO daily_sales VALUES ('2025-03-01',500),('2025-03-02',300),('2025-03-03',300),('2025-03-04',900);
SELECT day, cents,
       SUM(cents) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running
FROM daily_sales
ORDER BY day;
